const plan = $('Build Test Plan').all().map(function (i) { return i.json; });
const posts = $('POST Booth Scan').all().map(function (i) { return i.json; });
const rows = $('Read Final Decisions').all().map(function (i) { return i.json; }).filter(function (r) { return r && r.scan_id; });
const byScan = {};
for (const r of rows) byScan[r.scan_id] = r;

const results = plan.map(function (p, idx) {
  const post = posts[idx] || {};
  const body = (post && post.body && typeof post.body === 'object') ? post.body : post;
  const status = post && post.statusCode != null ? Number(post.statusCode) : null;
  const row = byScan[p.scan_id] || null;

  let raw = {};
  if (row && row.raw_json) { try { raw = JSON.parse(row.raw_json); } catch (e) { raw = {}; } }
  const d = raw.decision || raw;

  let slack = {};
  if (row && row.slack_json) { try { slack = JSON.parse(row.slack_json) || {}; } catch (e) { slack = {}; } }

  const answered = String((body && (body.provisional_classification || body.classification)) || '') || null;
  const stored = row ? (String(row.classification || '') || null) : null;
  const persona = String(d.persona || (body && (body.provisional_persona || body.persona)) || '') || null;
  const channel = String((raw.routing && raw.routing.channel) || '') || null;
  const finalScore = row && row.score != null ? Number(row.score) : null;
  const er = raw.employee_resolution || {};

  const slackDeliveries = Array.isArray(slack.deliveries) ? slack.deliveries : [];
  const slackDelivered = Number(slack.delivered_count || 0);
  const slackFailed = Number(slack.failed_count || 0);
  const slackErrors = slackDeliveries.filter(function (x) { return x && !x.ok; }).map(function (x) { return String(x.kind || 'post') + ': ' + String(x.error || 'unknown error'); });
  const slackReceipt = row ? Boolean(row.slack_json) : false;
  const slackExpected = Boolean(channel) && stored !== 'invalid';
  const expectAccepted = !(p.expect && p.expect.accepted === false);
  const deliveryStatus = row ? (String(row.status || '') || null) : null;

  const checks = [];
  if (expectAccepted) {
    checks.push({ check: 'webhook accepted the scan', pass: Boolean(body && body.accepted === true), got: (body && body.status) || ('HTTP ' + status) });
    checks.push({ check: 'a decision row was stored', pass: Boolean(row), got: row ? 'oak_deliveries row present' : 'no row for ' + p.scan_id });
    if (row) {
      checks.push({
        check: 'the delivery ledger reached status complete',
        pass: deliveryStatus === 'complete',
        got: deliveryStatus === 'complete' ? 'status is complete' : ((deliveryStatus ? 'status is still ' + deliveryStatus : 'the row carries no status') + ' after the ' + (p.settle_seconds == null ? 'settle' : p.settle_seconds + 's settle') + ' wait - re-read the row to tell a pipeline still running from one that never reached Persist Complete Delivery')
      });
    }
  } else {
    checks.push({ check: 'webhook rejected the scan', pass: !(body && body.accepted === true), got: (body && body.status) || ('HTTP ' + status) });
    checks.push({ check: 'no decision row was stored', pass: !row, got: row ? 'oak_deliveries row present for ' + p.scan_id + ' - the scan was not rejected' : 'no oak_deliveries row for ' + p.scan_id + ', which is correct for a rejected scan' });
  }
  if (expectAccepted && slackExpected) {
    checks.push({
      check: 'Slack actually delivered the alert',
      pass: slackReceipt ? (slackDelivered > 0 && slackFailed === 0) : false,
      got: !slackReceipt ? 'no Slack receipt was recorded' : (slackErrors.length ? slackErrors.join(' | ') : (slackDelivered + ' delivered, ' + slackFailed + ' failed'))
    });
  }
  if (expectAccepted && p.expect) {
    if (p.expect.classification) checks.push({ check: 'classification is ' + p.expect.classification, pass: stored === p.expect.classification, got: stored || 'none' });
    if (p.expect.persona) checks.push({ check: 'persona is ' + p.expect.persona, pass: persona === p.expect.persona, got: persona || 'none' });
    if (p.expect.channel !== undefined) checks.push({ check: 'routed to #' + p.expect.channel, pass: channel === p.expect.channel, got: channel ? ('#' + channel) : 'no channel' });
  }
  const failures = checks.filter(function (c) { return !c.pass; });

  return {
    lead: p.lead,
    suite: p.suite,
    label: p.label,
    scan_id: p.scan_id,
    expectations: p.expect ? 'checked' : 'none supplied',
    verdict: failures.length ? 'FAIL' : 'PASS',
    answered_to_scanner: answered,
    stored_after_pipeline: stored,
    delivery_status: deliveryStatus,
    changed_after_the_202: Boolean(answered && stored && answered !== stored),
    persona: persona,
    score: finalScore,
    rule_summary: d.rule_summary || null,
    slack_channel: channel,
    slack_delivered: slackReceipt ? slackDelivered : null,
    slack_errors: slackErrors,
    slack_threaded: Boolean(slack.threaded),
    hubspot_contact_id: ((raw.crm_context || {}).hubspot_contact_id) || null,
    company_created: Boolean((raw.crm_context || {}).company_created),
    headcount: er.employees == null ? 'not established' : (er.employees + ' from ' + String(er.source || '').replace(/_/g, ' ') + ' at ' + Math.round(Number(er.confidence || 0) * 100) + '%'),
    enrichment_cache_hit: Boolean(raw.enrichment_cache_hit),
    repeat_scan: Boolean(d.repeat_scan),
    scan_number: d.scan_count || 1,
    why: p.notes || null,
    checks: checks,
    failures: failures.map(function (f) { return f.check + ' - got ' + f.got; })
  };
});

const failed = results.filter(function (r) { return r.verdict === 'FAIL'; });
const sourceLabels = { paste_json_here: 'JSON pasted into the Paste JSON Here node', data_table: 'enabled rows in oak_test_payloads', fallback: 'built-in safety net (the table was empty)' };
const src = (plan[0] && plan[0].source) || 'unknown';
const slackProblems = results.filter(function (r) { return r.slack_errors.length; });
return [{ json: {
  ran_at: new Date().toISOString(),
  scans_came_from: sourceLabels[src] || src,
  verdict: failed.length ? 'FAIL' : 'PASS',
  total: results.length,
  passed: results.length - failed.length,
  failed: failed.length,
  reset_first: Boolean(plan[0] && plan[0].reset_before_run),
  enrichment_reused_from_cache: results.filter(function (r) { return r.enrichment_cache_hit; }).length,
  slack_alerts_delivered: results.reduce(function (n, r) { return n + Number(r.slack_delivered || 0); }, 0),
  slack_failures: slackProblems.map(function (r) { return r.label + ': ' + r.slack_errors.join(' | '); }),
  headline: results.map(function (r) {
    return r.lead + '. ' + r.label + ' -> ' + (r.stored_after_pipeline || 'no decision') + (r.slack_channel ? ' (#' + r.slack_channel + ')' : '') + ' [' + r.verdict + ']';
  }),
  results: results
} }];

/* ===== Defaults. Override reset, gap_seconds, settle_seconds in the pasted JSON. ===== */
// n8n variables win when set. Unset, WEBHOOK_URL keeps this instance and RUN_SUITE keeps the enabled rows.
const WEBHOOK_URL    = String($vars.OAK_BOOTH_WEBHOOK_URL || '').trim() || 'https://oak-noam.app.n8n.cloud/webhook/oak-event/scan';
const RUN_SUITE      = String($vars.OAK_TEST_SUITE || '').trim() || 'enabled';   // 'enabled' | 'all' | a suite name
const GAP_MS         = 15000;
const SETTLE_SECONDS = 90;
const TEST_EVENT_ID  = 'oak-live-event-2026';
const RESET_ON_MANUAL_RUN = true;
/* ==================================================================================== */

const FALLBACK = [
  { label: 'Lead 1 - The Ideal Target',
    payload: { scan_id: 'evt_9901', first_name: 'Rachel', last_name: 'Green', email: 'rachel.green@apex-finance.com', job_title: 'Chief Information Security Officer', company_name: 'Apex Financial Services', scanned_at: '2026-07-19T11:00:00Z', notes_from_booth: 'Currently using SailPoint, renewal coming up in 5 months. Complaining about manual access reviews.' } },
  { label: 'Lead 2 - The Technical Practitioner',
    payload: { scan_id: 'evt_9902', first_name: 'Hiroshi', last_name: 'Tanaka', email: 'hiroshi.t@cloudscale-tech.io', job_title: 'Lead Identity Infrastructure Architect', company_name: 'CloudScale Technologies', scanned_at: '2026-07-19T11:05:00Z', notes_from_booth: 'Struggling with non-human identities and AI agent sprawl. Built a homegrown tool to track API keys.' } },
  { label: 'Lead 3 - The Bad Fit (Too Small)',
    payload: { scan_id: 'evt_9903', first_name: 'David', last_name: 'Miller', email: 'david@boutiquesecurity.co.il', job_title: 'Head of IT', company_name: 'Boutique Security Ltd', scanned_at: '2026-07-19T11:10:00Z', notes_from_booth: 'SaaS-only shop, 80 employees. Looking for a basic access tool.' } },
  { label: 'Lead 4 - The Competitor / Intel Scan',
    payload: { scan_id: 'evt_9904', first_name: 'Sarah', last_name: 'Connor', email: 's.connor@veza.com', job_title: 'Director of Product Management', company_name: 'Veza Technologies', scanned_at: '2026-07-19T11:15:00Z', notes_from_booth: 'Asked a lot of detailed questions about our ConnectAny architecture.' } }
];

// Every table row, enabled or not. RUN_SUITE picks which rows supply the scans; all rows supply expectations.
const allRows = $input.all().map(function (i) { return i.json; })
  .filter(function (r) { return r && r.payload_json; })
  .sort(function (a, b) { return Number(a.sort_order || 0) - Number(b.sort_order || 0); });

function parseRow(r, i) {
  const at = 'Row "' + (r.label || (i + 1)) + '"';
  let payload;
  try { payload = JSON.parse(r.payload_json); }
  catch (e) { throw new Error(at + ' has invalid payload_json: ' + e.message); }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error(at + ' payload_json must be a single JSON object.');
  if (!payload.scan_id) throw new Error(at + ' has no scan_id in payload_json.');
  let expect = null;
  if (r.expect_json) {
    try { const e2 = JSON.parse(r.expect_json); if (e2 && typeof e2 === 'object' && Object.keys(e2).length) expect = e2; }
    catch (e) { throw new Error(at + ' has invalid expect_json: ' + e.message); }
  }
  return { payload: payload, expect: expect, row: r };
}

const parsedRows = allRows.map(parseRow);
const expectByScan = {};
const labelByScan = {};
const notesByScan = {};
for (const p of parsedRows) {
  const id = String(p.payload.scan_id);
  if (p.expect) expectByScan[id] = p.expect;
  if (p.row.label) labelByScan[id] = p.row.label;
  if (p.row.notes) notesByScan[id] = p.row.notes;
}

// Pasted scans are the task payload verbatim. Expectations are looked up by scan_id.
function normalize(list, where) {
  return list.map(function (p, i) {
    const at = where + ' item ' + (i + 1);
    if (!p || typeof p !== 'object' || Array.isArray(p)) throw new Error(at + ' is not a JSON object.');
    if (!p.scan_id) throw new Error(at + ' has no scan_id. Intake uses it to block webhook replays.');
    const id = String(p.scan_id);
    const nm = [p.first_name, p.last_name].filter(Boolean).join(' ').trim();
    const body = Object.assign({}, p);
    const inline = (p.expect && typeof p.expect === 'object' && Object.keys(p.expect).length) ? p.expect : null;
    delete body.expect;
    return { suite: where, label: labelByScan[id] || nm || id, expect: inline || expectByScan[id] || null, payload: body, notes: notesByScan[id] || null };
  });
}

let quick = {};
try { quick = $('Paste JSON Here').first().json || {}; } catch (e) { quick = {}; }
const quickScans = Array.isArray(quick.scans) ? quick.scans : (Array.isArray(quick) ? quick : []);
const quickReset = (quick && typeof quick.reset === 'boolean') ? quick.reset : null;
const gapMs = (quick && Number(quick.gap_seconds) > 0) ? Math.round(Number(quick.gap_seconds) * 1000) : GAP_MS;
const settle = (quick && Number(quick.settle_seconds) > 0) ? Math.round(Number(quick.settle_seconds)) : SETTLE_SECONDS;
const reset = (quickReset !== null) ? quickReset : RESET_ON_MANUAL_RUN;

let rows;
let source;

if (quickScans.length) {
  source = 'paste_json_here';
  rows = normalize(quickScans, 'paste_json_here');
} else {
  // There is no bulk toggle for enabled, so RUN_SUITE is the switch: 'enabled' is the default run,
  // 'all' ignores enabled, and any other value runs the rows whose suite equals it.
  const selected = parsedRows.filter(function (p) {
    if (RUN_SUITE === 'enabled') return p.row.enabled === true;
    if (RUN_SUITE === 'all') return true;
    return String(p.row.suite || 'default') === RUN_SUITE;
  });
  // A mistyped suite must not quietly fall back to the four task leads and report green.
  if (!selected.length && RUN_SUITE !== 'enabled' && RUN_SUITE !== 'all') {
    const suites = parsedRows.map(function (p) { return String(p.row.suite || 'default'); }).filter(function (s, i, a) { return a.indexOf(s) === i; });
    throw new Error('OAK_TEST_SUITE is "' + RUN_SUITE + '" but no oak_test_payloads row has that suite. Use enabled, all, or one of: ' + (suites.join(', ') || 'none') + '.');
  }
  if (selected.length) {
    source = RUN_SUITE === 'enabled' ? 'data_table' : ('oak_test_payloads, OAK_TEST_SUITE=' + RUN_SUITE);
    rows = selected.map(function (p) {
      const nm = [p.payload.first_name, p.payload.last_name].filter(Boolean).join(' ').trim();
      return { suite: p.row.suite || 'default', label: p.row.label || nm || String(p.payload.scan_id), expect: p.expect, payload: p.payload, notes: p.row.notes || null };
    });
  } else {
    source = 'fallback';
    rows = FALLBACK.map(function (r) {
      const id = String(r.payload.scan_id);
      return { suite: 'task', label: r.label, expect: expectByScan[id] || null, payload: r.payload, notes: null };
    });
  }
}

const seen = {};
for (const r of rows) {
  if (seen[r.payload.scan_id]) throw new Error('Two scans in this run share scan_id "' + r.payload.scan_id + '". The replay guard would drop the second one.');
  seen[r.payload.scan_id] = true;
}

return rows.map(function (r, i) {
  return { json: {
    lead: i + 1,
    suite: r.suite,
    label: r.label,
    notes: r.notes,
    expect: r.expect,
    payload: r.payload,
    scan_id: String(r.payload.scan_id),
    email: r.payload.email || null,
    source: source,
    webhook_url: WEBHOOK_URL,
    reset_before_run: reset,
    reset_filter: reset ? TEST_EVENT_ID : '__no_reset__',
    test_event_id: TEST_EVENT_ID,
    gap_ms: gapMs,
    settle_seconds: settle
  } };
});
